// ============================================================================
// 4. PARSE BRIEF & STAGE FINAL RENDER
// ============================================================================
let raw = $json.output || "";
raw = raw.replace(/```json/gi, "").replace(/```/g, "").trim();

let data;
if (raw) {
  try { data = JSON.parse(raw); } catch(e) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { data = JSON.parse(m[0]); } catch(err){} }
  }
}

const upstream = ($('2. Fetch Next MERN Concept (Auto-Advance)').item?.json) || {};
const concept = data?.concept || upstream.concept || {};
const meta = data?.meta || upstream.meta || {};

const finalBrief = {
  ...concept,
  formatted_caption: data?.formatted_caption || (
    `${concept.badge || 'MERN STACK'}: ${concept.headline || ''}\n\n` +
    `${concept.golden_rule || 'Master clean code principles every day.'}\n\n` +
    "Save this concept for your daily MERN roadmap 🚀\n\n" +
    "#mernstack #webdevelopment #reactjs #nodejs #mongodb #javascript #codiva #coding"
  )
};

return [{
  json: {
    brief: finalBrief,
    caption: finalBrief.formatted_caption,
    curriculum_meta: meta
  }
}];

// ============================================================================
// 6. PREPARE FINAL POST RECORD
// ============================================================================
const canvasData = $json;

if (!canvasData.image_url || !canvasData.image_url.startsWith("http")) {
  throw new Error("Invalid or missing image_url from canvas engine: " + JSON.stringify(canvasData));
}

const staged = ($('4. Brief Parser & Stager').item?.json) || {};
const config = ($('1. Brand DNA & Config').item?.json?.config) || { TEST_MODE: true, INSTAGRAM_ACCOUNT_ID: "17841475951559107" };

const postId = "CODIVA-MERN-" + Date.now();
const testMode = (config.TEST_MODE === true);

return [{
  json: {
    post_id: postId,
    created_at: new Date().toISOString(),
    series: "MERN Stack Mastery",
    topic: staged.brief?.headline || "MERN Concept",
    headline: staged.brief?.headline,
    badge: staged.brief?.badge,
    caption: staged.caption,
    image_url: canvasData.image_url,
    format: "1080x1350_clean_mobile_comparison",
    aspect_ratio: "4:5 (1080x1350)",
    test_mode: testMode,
    ig_user_id: config.INSTAGRAM_ACCOUNT_ID || "17841475951559107",
    status: testMode ? "test_mode_simulation" : "publishing_live",
    progress: staged.curriculum_meta
  }
}];

// ============================================================================
// 8A. TEST MODE SUCCESS SUMMARY (SIMULATION)
// ============================================================================
const data = $input.first().json;

return [{
  json: {
    simulation_status: "SUCCESS_PREVIEW_READY",
    message: "TEST_MODE is ACTIVE: The clean mobile card was rendered and hosted successfully without calling Instagram Graph API.",
    post_id: data.post_id,
    series: data.series,
    badge: data.badge,
    headline: data.headline,
    image_url: data.image_url,
    caption: data.caption,
    curriculum_progression: data.progress,
    scheduled_daily_times: "7:00 PM IST and 10:00 PM IST",
    how_to_publish_live: "To publish live to @codiva_labs on Instagram, change TEST_MODE to false in Node 1 (Brand DNA & Config)."
  }
}];
